Job S01: claims_enrich.sas. Claim-level payment history and indicators.
Parameters: AsOfDate=2025-12-31.

Code:
  1 | /******************************************************************************
  2 |   Program  : claims_enrich.sas
  3 |   Purpose  : Claim-level payment history for the risk team. One row per claim
  4 |              on the claims register with its payments up to the reporting
  5 |              date: payment and recovery counts, paid to date, the paid split
  6 |              by payment type (gross, and net of recoveries), the first and
  7 |              last payment dates and a recovery marker. Read by the customer
  8 |              risk scoring (risk_scoring.sas).
  9 |   Inputs   : stg.claims, stg.claim_payments
 10 |   Output   : dw.claims_enriched (rebuilt on every run)
 11 |   Params   : as_of - reporting date (SAS date), set by the scheduler
 12 |   Author   : DOS
 13 | 
 14 |   Change log
 15 |     2014-03-10  DOS   Initial version
 16 |     2015-08-24  DOS   Recoveries counted and flagged for the subrogation desk
 17 |                       (CR-0611)
 18 |     2017-01-16  AK    Paid split by payment type; gross and net paid (CR-1042)
 19 |     2018-11-05  AK    Payments dated after the reporting date left out
 20 |                       (INC-1677)
 21 |     2019-09-30  AK    Line of business and status tidied for the MI pack
 22 |                       (CR-1502)
 23 |     2021-06-14  SMcC  Claims with nothing paid yet kept, with has_payment, for
 24 |                       risk_scoring.sas (CR-1873)
 25 | ******************************************************************************/
 26 | 
 27 | /* claims register */
 28 | proc sort data=stg.claims(keep=claim_id claim_number policy_id customer_id lob_code
 29 |                                loss_date reported_date status)
 30 |           out=work.claims;
 31 |   by claim_id;
 32 | run;
 33 | 
 34 | /* payments to the reporting date, claim by claim in the order they were keyed */
 35 | proc sort data=stg.claim_payments(keep=claim_id payment_date amount payment_type _row_seq
 36 |                                   where=(payment_date <= &as_of))
 37 |           out=work.payments;
 38 |   by claim_id _row_seq;
 39 | run;
 40 | 
 41 | /* roll the payments up to one row per claim */
 42 | data work.pay_summary(keep=claim_id n_payments n_recoveries total_paid indemnity_amt
 43 |                            expense_amt recovery_amt first_payment_date last_payment_date
 44 |                            recovery_flag);
 45 |   set work.payments;
 46 |   by claim_id;
 47 |   length ptype $12;
 48 |   retain n_payments n_recoveries total_paid indemnity_amt expense_amt recovery_amt
 49 |          first_payment_date last_payment_date recovery_flag;
 50 |   format first_payment_date last_payment_date date9.;
 51 | 
 52 |   if first.claim_id then do;
 53 |     n_payments    = 0;
 54 |     n_recoveries  = 0;
 55 |     total_paid    = 0;
 56 |     indemnity_amt = 0;
 57 |     expense_amt   = 0;
 58 |     recovery_amt  = 0;
 59 |     recovery_flag = 0;
 60 |     first_payment_date = payment_date;
 61 |   end;
 62 | 
 63 |   n_payments + 1;
 64 |   total_paid + amount;
 65 | 
 66 |   /* paid split by payment type (keyed in mixed case) */
 67 |   ptype = upcase(strip(payment_type));
 68 |   if ptype = 'INDEMNITY' then indemnity_amt = indemnity_amt + amount;
 69 |   else if ptype = 'EXPENSE' then expense_amt = expense_amt + amount;
 70 |   else if ptype = 'RECOVERY' then recovery_amt = recovery_amt + amount;
 71 | 
 72 |   /* recoveries (salvage, third-party) come through as negative amounts */
 73 |   if amount < 0 then do;
 74 |     recovery_flag = 1;
 75 |     n_recoveries + 1;
 76 |   end;
 77 | 
 78 |   last_payment_date = payment_date;
 79 |   if last.claim_id then output;
 80 | run;
 81 | 
 82 | /* enrich the register: every claim is reported, paid or not */
 83 | data dw.claims_enriched(keep=claim_id claim_number policy_id customer_id lob_code
 84 |                              loss_date reported_date status n_payments n_recoveries
 85 |                              total_paid indemnity_amt expense_amt recovery_amt gross_paid
 86 |                              net_paid first_payment_date last_payment_date recovery_flag
 87 |                              has_payment);
 88 |   merge work.claims(in=c) work.pay_summary(in=p);
 89 |   by claim_id;
 90 |   if c;
 91 | 
 92 |   lob_code = upcase(strip(lob_code));
 93 |   status   = upcase(strip(status));
 94 | 
 95 |   has_payment = p;
 96 |   if not p then do;
 97 |     n_payments    = 0;
 98 |     n_recoveries  = 0;
 99 |     total_paid    = 0;
100 |     recovery_flag = 0;
101 |   end;
102 | 
103 |   gross_paid = indemnity_amt + expense_amt;
104 |   net_paid   = sum(indemnity_amt, expense_amt, recovery_amt);
105 | run;
106 | 
107 | proc datasets lib=work nolist;
108 |   delete claims payments pay_summary;
109 | quit;

Views for impact queries:
- stg_claims (stg.claims): claim_id int, claim_number string, policy_id int, customer_id int, lob_code string, loss_date date, reported_date date, status string, closed_date date, cause_code string, handler_code string, description string, _row_seq int
- stg_claim_payments (stg.claim_payments): payment_id int, claim_id int, payment_date date, amount decimal(12,2), payment_type string, payee_type string, _row_seq int
- golden_dw_claims_enriched (the legacy output dw.claims_enriched): claim_id double, claim_number string, policy_id double, customer_id double, lob_code string, loss_date date, reported_date date, status string, n_payments double, n_recoveries double, total_paid double, indemnity_amt double, expense_amt double, recovery_amt double, first_payment_date date, last_payment_date date, recovery_flag double, has_payment double, gross_paid double, net_paid double

